'use client';
import {useState} from 'react';
import AppShell from '../../app/components/app-shell';
import QuickTasks from '../../app/quick-tasks/quick-tasks';
import type {QuickTask,QuickTasksData} from '../../lib/quick-task-types';
import type {Member} from '../../lib/agent-types';
const company={id:'11111111-1111-4111-8111-111111111111',name:'Northstar Demo',time_zone:'Europe/London'};
const people=[{id:'33333333-3333-4333-8333-333333333333',name:'Taylor Example'},{id:'44444444-4444-4444-8444-444444444444',name:'Casey Sample'},{id:'55555555-5555-4555-8555-555555555555',name:'Jordan Demo'}];
const task:QuickTask={id:'66666666-6666-4666-8666-666666666666',tenant_id:company.id,title:'Prepare the opening checklist',description:'Review the shared opening checklist and confirm supplies are ready for the team.',mode:'group',publication:'published',status:'open',archived:false,revision:1,created_by:'77777777-7777-4777-8777-777777777777',created_at:'2026-10-03T23:30:00Z',start_date:'2026-10-04',due_date:'2026-10-05',completed_by:null,completed_name:null,completed_at:null,assignees:people.slice(0,2),overdue:false,canComplete:true};
export default function Review(){const [role,setRole]=useState<Member['role']>('owner');const [visible,setVisible]=useState(true);const [key,setKey]=useState(0);const [large,setLarge]=useState(false);const manage=role==='owner'||role==='admin';const data:QuickTasksData={company,role,actorId:'77777777-7777-4777-8777-777777777777',agent:people[0],capabilities:{canCreate:manage,canManage:manage,canViewAll:manage},assignableAgents:manage?(large?[...people.slice(0,2),...Array.from({length:98},(_,index)=>({id:`99999999-9999-4999-8999-${String(index).padStart(12,'0')}`,name:`Roster Example ${String(index).padStart(3,'0')}`}))]:people):[],assignableAgentsHasMore:manage&&large,assignableAgentsCursor:manage&&large?'synthetic-initial-users':null,tasks:[task],counts:{total:1,open:1,done:0,overdue:0},nextCursor:null,serverTime:'2026-10-04T09:00:00Z',timeZone:company.time_zone};return <AppShell companyName={company.name} companyId={company.id} activeModule="users" accountName="Synthetic reviewer"><div aria-label="Synthetic review controls" style={{display:'flex',gap:12,padding:12}}><button onClick={()=>setRole(role==='owner'?'employee':'owner')}>Switch demo role</button><button onClick={()=>setVisible(!visible)}>Toggle demo departure</button><button onClick={()=>setKey(key+1)}>Remount demo tasks</button><button onClick={()=>{setLarge(true);setKey(key+1);}}>Use large demo roster</button></div>{visible?<QuickTasks key={key} company={company} role={role} initialData={data}/>:<p>Demo departed</p>}</AppShell>;}
